<?php
namespace App\Controller\Admin;
use App\Entity\AdditionalCost; use App\Enum\CostCalculationMethod; use EasyCorp\Bundle\EasyAdminBundle\Config\Crud; use EasyCorp\Bundle\EasyAdminBundle\Controller\AbstractCrudController; use EasyCorp\Bundle\EasyAdminBundle\Field\BooleanField; use EasyCorp\Bundle\EasyAdminBundle\Field\ChoiceField; use EasyCorp\Bundle\EasyAdminBundle\Field\IdField; use EasyCorp\Bundle\EasyAdminBundle\Field\MoneyField; use EasyCorp\Bundle\EasyAdminBundle\Field\NumberField; use EasyCorp\Bundle\EasyAdminBundle\Field\TextField;
class AdditionalCostCrudController extends AbstractCrudController { public static function getEntityFqcn(): string{return AdditionalCost::class;} public function configureCrud(Crud $crud): Crud{return $crud->setEntityLabelInSingular('Gasto adicional')->setEntityLabelInPlural('Gastos adicionales');} public function configureFields(string $p): iterable {yield IdField::new('id')->onlyOnIndex();yield TextField::new('name','Concepto');yield ChoiceField::new('method','Cálculo')->setChoices(array_combine(array_map(fn($v)=>$v->label(),CostCalculationMethod::cases()),CostCalculationMethod::cases()));yield MoneyField::new('rate','Valor / tarifa')->setCurrency('ARS')->setStoredAsCents(false);yield TextField::new('rateUnit','Unidad de tarifa')->setHelp('Ej.: hora, km, uso')->hideOnIndex();yield BooleanField::new('labor','Es mano de obra');yield BooleanField::new('shared','Compartido por presupuesto');yield MoneyField::new('acquisitionValue','Valor de adquisición')->setCurrency('ARS')->setStoredAsCents(false)->hideOnIndex();yield NumberField::new('usefulLifeUses','Vida útil estimada (usos)')->hideOnIndex();yield BooleanField::new('active','Activo');} }
